INSERT INTO media_picks (kind, name, creator, url, blurb, sort_order, is_published)
VALUES
('youtube', $b$HowToBBQRight$b$, $b$Malcom Reed$b$, $b$https://www.youtube.com/@howtobbqright$b$, $b$Malcom Reed makes the complicated feel doable: clear, repeatable recipes and competition tricks delivered without a scrap of ego. If you've ever ruined a rack of ribs, start here.$b$, 10, true),
('youtube', $b$BBQ Pit Boys$b$, NULL, $b$https://www.youtube.com/@bbqpitboys$b$, $b$No frills, no fuss, no gatekeeping — just backyard fire and classic recipes from a crew that's been at it since the early days of the internet. Comfort food for the eyes.$b$, 20, true),
('youtube', $b$Mad Scientist BBQ$b$, $b$Jeremy Yoder$b$, $b$https://www.youtube.com/@madscientistbbq$b$, $b$Jeremy Yoder brings the thermometer and the "why" — the science of fire, temperature and technique, tested rather than assumed. For the cook who wants to understand, not just follow.$b$, 30, true),
('youtube', $b$Chuds BBQ$b$, $b$Bradley Robinson$b$, $b$https://www.youtube.com/@ChudsBbq$b$, $b$Bradley Robinson goes deep on Texas craft: butchery, pit building, and the small technical moves that separate good brisket from great. Beautifully shot and genuinely useful.$b$, 40, true),
('youtube', $b$Meat Church BBQ$b$, $b$Matt Pittman$b$, $b$https://www.youtube.com/@meatchurchbbq$b$, $b$Matt Pittman makes outdoor cooking feel like a good time — approachable recipes, honest rubs, and the sense that anyone can pull this off. Sunday-afternoon energy.$b$, 50, true),
('youtube', $b$BBQ with Franklin$b$, $b$Aaron Franklin$b$, $b$https://www.youtube.com/@BBQwithFranklin$b$, $b$The Franklin Barbecue pitmaster, patiently explaining the Texas method that made Austin queue for hours. Few people teach fire and patience this well.$b$, 60, true),
('youtube', $b$Pitmaster X$b$, $b$Roel Westra$b$, $b$https://www.youtube.com/@pitmasterx$b$, $b$Roel Westra cooks the whole world — international recipes, gear and technique, with an appetite that doesn't respect borders. Very much our kind of map.$b$, 70, true),
('youtube', $b$Heath Riles BBQ$b$, $b$Heath Riles$b$, $b$https://www.youtube.com/@HeathRilesBBQ$b$, $b$A multi-time Memphis in May champion showing his working: competition recipes and technique from someone who's actually won. Precise, generous, and quietly obsessed.$b$, 80, true),
('book', $b$Franklin Barbecue: A Meat-Smoking Manifesto$b$, $b$Aaron Franklin & Jordan Mackay$b$, $b$https://www.amazon.com/Franklin-Barbecue-Meat-Smoking-Manifesto-Cookbook/dp/1607747200$b$, $b$The closest thing barbecue has to a sacred text — Franklin on fire, smoke, wood and the brisket that made Austin queue for hours. If you read only one, read this.$b$, 10, true),
('book', $b$Fire Food: The Ultimate BBQ Cookbook$b$, $b$Christian Stevenson (DJ BBQ)$b$, $b$https://www.amazon.co.uk/Fire-Food-Ultimate-BBQ-Cookbook/dp/1787131548$b$, $b$DJ BBQ cooks with the volume up — big flavors, big fun, and recipes that treat live fire as a party rather than an exam.$b$, 20, true),
('book', $b$Beer-Can Chicken$b$, $b$Steven Raichlen$b$, $b$https://www.amazon.com/Beer-Can-Chicken-Foolproof-Crispiest-Crackliest/dp/1523526211$b$, $b$A whole book built around one gloriously silly, genuinely brilliant idea — plus a hundred other reasons to stand something upright over the coals.$b$, 30, true),
('book', $b$Meathead: The Science of Great Barbecue and Grilling$b$, $b$Meathead Goldwyn$b$, $b$https://www.amazon.com/Meathead-Science-Great-Barbecue-Grilling/dp/054401846X$b$, $b$Meathead takes a blowtorch to the myths — the actual science of what happens on the grill, footnoted and field-tested. Ends a lot of arguments.$b$, 40, true),
('book', $b$Project Smoke$b$, $b$Steven Raichlen$b$, $b$https://www.amazon.com/Project-Smoke-Irresistible-Adventurous-Bacon-Bourbon/dp/0761189238$b$, $b$A clear, confident on-ramp to smoking: the techniques, the gear and the recipes, laid out so a first-timer can actually follow them.$b$, 50, true),
('book', $b$Franklin Steak$b$, $b$Aaron Franklin & Jordan Mackay$b$, $b$https://www.amazon.com/Franklin-Steak-Dry-Aged-Live-Fired-Cookbook/dp/0399580960$b$, $b$The Franklin obsession turned on beef beyond brisket — dry-aging, fire and the perfect steak, explained with the same patient care.$b$, 60, true),
('book', $b$The Burger Book$b$, $b$Christian Stevenson (DJ BBQ)$b$, $b$https://www.amazon.com/Burger-Book-Banging-Burgers-Sauces/dp/1787133648$b$, $b$Everything DJ BBQ knows about a properly banging burger — patties, sauces and the confidence to stop overthinking it.$b$, 70, true),
('book', $b$The Barbecue! Bible$b$, $b$Steven Raichlen$b$, $b$https://www.amazon.com/Barbecue-Bible-Great-Grilling-Recipes/dp/0761149449$b$, $b$Raichlen's around-the-world tour of live fire — hundreds of recipes from every continent that grills. A passport as much as a cookbook, and very on-brand for an atlas.$b$, 80, true),
('book', $b$Smokin' with Myron Mixon$b$, $b$Myron Mixon$b$, $b$https://www.amazon.com/Smokin-Myron-Mixon-Recipes-Winningest/dp/0345528532$b$, $b$The winningest man in competition barbecue, loud and unfiltered, handing over the recipes that beat everyone else. Not humble, and doesn't need to be.$b$, 90, true),
('book', $b$Big Bob Gibson's BBQ Book$b$, $b$Chris Lilly$b$, $b$https://www.amazon.com/Big-Bob-Gibsons-BBQ-Book/dp/0307452347$b$, $b$Alabama royalty — Chris Lilly on the pits, the white sauce and the championship habits behind one of America's great barbecue names.$b$, 100, true),
('book', $b$Rodney Scott's World of BBQ$b$, $b$Rodney Scott & Lolis Eric Elie$b$, $b$https://www.amazon.com/Rodney-Scotts-World-BBQ-Cookbook/dp/198482693X$b$, $b$Whole-hog wisdom and a life story to match, from the South Carolina pitmaster who turned all-night fires into an art. Warm and unforgettable.$b$, 110, true),
('book', $b$How to Grill$b$, $b$Steven Raichlen$b$, $b$https://www.amazon.com/How-Grill-Complete-Illustrated-Techniques/dp/0761120149$b$, $b$The illustrated basics done properly — step-by-step technique for people who want to see exactly what "done right" looks like.$b$, 120, true),
('book', $b$Cool Smoke: The Art of Great Barbecue$b$, $b$Tuffy Stone$b$, $b$https://www.amazon.com/Cool-Smoke-Art-Great-Barbecue/dp/0399578723$b$, $b$A five-time world champion with a chef's precision — Tuffy Stone on the disciplined, repeatable side of great barbecue.$b$, 130, true),
('book', $b$Peace, Love & Barbecue$b$, $b$Mike Mills & Amy Mills$b$, $b$https://www.amazon.com/Peace-Love-Barbecue-Secrets-Legends/dp/1401303275$b$, $b$Part cookbook, part road trip — the Mills family chasing barbecue's characters and secrets across America. As much heart as recipe.$b$, 140, true),
('book', $b$Project Fire$b$, $b$Steven Raichlen$b$, $b$https://www.amazon.com/Project-Fire-Cutting-Edge-Techniques-Sizzling/dp/0761189017$b$, $b$Raichlen back on open flame — grilling, smoking and caveman cooking with a cutting-edge streak. For people who like their food a little dangerous.$b$, 150, true),
('book', $b$Franklin Smoke$b$, $b$Aaron Franklin & Jordan Mackay$b$, $b$https://www.amazon.com/Franklin-Smoke-Wood-Fire-Cookbook/dp/198486131X$b$, $b$The third Franklin book, all about wood and flavor — how smoke actually works, and how to bend it to your will.$b$, 160, true),
('book', $b$Diva Q's Barbecue$b$, $b$Danielle Bennett$b$, $b$https://www.amazon.com/Diva-Qs-Barbecue-Recipes-Competition/dp/177050219X$b$, $b$Danielle Bennett brings competition-grade recipes down to backyard level, with the energy of someone who genuinely wants you to win Sunday.$b$, 170, true),
('book', $b$Hardcore Carnivore$b$, $b$Jess Pryles$b$, $b$https://www.amazon.com/Hardcore-Carnivore-Cook-Meat-Mean/dp/178488171X$b$, $b$An Australian loose in Texas and entirely serious about meat — Jess Pryles on cuts, fire, and cooking it all like you mean it.$b$, 180, true),
('book', $b$Weber's Barbecue Bible$b$, $b$Jamie Purviance$b$, $b$https://www.amazon.com/Webers-Barbecue-Bible-Jamie-Purviance/dp/0761149422$b$, $b$The dependable house manual — hundreds of Weber-tested recipes for people who just want it to work, every time.$b$, 190, true),
('book', $b$Barbecue Sauces, Rubs, and Marinades$b$, $b$Steven Raichlen$b$, $b$https://www.amazon.com/Barbecue-Sauces-Rubs-Marinades-Bastes/dp/0761184887$b$, $b$The flavor toolkit — the bastes, rubs and mops that turn plain meat into something worth remembering. The one you'll actually splatter.$b$, 200, true),
('book', $b$The Brisket Chronicles$b$, $b$Steven Raichlen$b$, $b$https://www.amazon.com/Brisket-Chronicles-Smoke-Barbecue-Recipes/dp/1523503459$b$, $b$A whole book for the cut that breaks hearts — brisket every which way, from the smoker to the stovetop. Redemption for anyone it's beaten.$b$, 210, true),
('book', $b$Playing with Fire$b$, $b$Michael Symon$b$, $b$https://www.amazon.com/Michael-Symons-Playing-Fire-Fireplace/dp/1984826131$b$, $b$The chef and Iron Chef turned loose on live fire — bold, meat-forward cooking with restaurant polish and none of the fuss.$b$, 220, true),
('book', $b$Jamie's Food Tube: The BBQ Book$b$, $b$Christian Stevenson (DJ BBQ)$b$, $b$https://www.amazon.co.uk/Jamies-Food-Tube-Jamie-Olivers/dp/0718179188$b$, $b$DJ BBQ's pocket-sized starter — quick, cheeky, and exactly the nudge a nervous first-timer needs to light the thing.$b$, 230, true),
('book', $b$Charred: The Complete Guide to Vegetarian Grilling and Barbecue$b$, $b$Genevieve Taylor$b$, $b$https://www.amazon.co.uk/Charred-Complete-Guide-Vegetarian-Barbecue/dp/1787135837$b$, $b$Proof the fire doesn't have to be about meat — Genevieve Taylor gives vegetables the char, smoke and top billing they rarely get.$b$, 240, true),
('book', $b$Low and Slow$b$, $b$Neil Rankin$b$, $b$https://www.amazon.co.uk/Low-Slow-How-Cook-Meat/dp/1785031135$b$, $b$A chef's uncompromising take on cooking meat properly — opinionated, technical, and worth arguing with.$b$, 250, true),
('book', $b$Berber & Q$b$, $b$Josh Katz$b$, $b$https://www.amazon.co.uk/Berber-Q-Josh-Katz/dp/178503228X$b$, $b$Smoke meets the Middle East and North Africa — Josh Katz's London grill house on the plate, all char, spice and swagger.$b$, 260, true),
('book', $b$Planet Barbecue!$b$, $b$Steven Raichlen$b$, $b$https://www.amazon.com/Planet-Barbecue-Steven-Raichlen/dp/0761148019$b$, $b$Raichlen's biggest world tour yet — hundreds of recipes from dozens of countries. If our map had a cookbook cousin, this would be it.$b$, 270, true),
('book', $b$Smoking Meat$b$, $b$Jeff Phillips$b$, $b$https://www.amazon.com/Smoking-Meat-Essential-Guide-Barbecue/dp/0778802616$b$, $b$The friendly beginner's guide to the smoker — the fundamentals, patiently explained, for anyone starting from zero.$b$, 280, true),
('book', $b$The Wood Pellet Smoker and Grill Cookbook$b$, $b$Peter Jautaikis$b$, $b$https://www.amazon.com/Wood-Pellet-Smoker-Grill-Cookbook/dp/1624142786$b$, $b$For the pellet-grill crowd — dialed-in recipes and settings that make the most of set-it-and-watch-it cooking.$b$, 290, true),
('book', $b$Praise the Lard$b$, $b$Mike Mills & Amy Mills$b$, $b$https://www.amazon.com/Praise-Lard-Recipes-Revelations-Legendary/dp/054470526X$b$, $b$More stories and recipes from the Mills family — a warm, funny second helping from 17th Street Barbecue royalty.$b$, 300, true),
('book', $b$New School Barbecue$b$, $b$Evan LeRoy$b$, $b$https://www.amazon.com/New-School-Barbecue-Next-Level-Smoking/dp/1984862146$b$, $b$Austin's next generation — Evan LeRoy on sustainable, whole-animal Texas cooking that respects the old rules while breaking a few.$b$, 310, true),
('book', $b$Serial Griller$b$, $b$Matt Moore$b$, $b$https://www.amazon.com/Serial-Griller-Fire-Cooking-Techniques/dp/0062942733$b$, $b$A cross-country hunt for grilling's obsessives — Matt Moore collecting the techniques and characters who cook over fire for a living.$b$, 320, true),
('podcast', $b$HowToBBQRight Podcast$b$, $b$Malcom & Rachelle Reed$b$, $b$https://open.spotify.com/show/0NC8qIuuQfnPb8KPKe0hvp$b$, $b$Malcom and Rachelle Reed talk recipes, tips and competition life each week — the easy back-and-forth of two people who clearly still love this. Good company on a long cook.$b$, 10, true),
('podcast', $b$The BBQ Central Show$b$, $b$Greg Rempe$b$, $b$https://open.spotify.com/show/6ilvJS8JcNorp23HXs9D7B$b$, $b$Greg Rempe has spent years interviewing pitmasters, industry folk and the occasional troublemaker — the long-running watering hole for barbecue news and opinion.$b$, 20, true),
